def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 2 else 35.0))

    need_units = int(supply / WATER_REQ)
    if need_units < 0:
        need_units = 0

    prev_bids = []
    dangerous_prev = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 80.0:
                dangerous_prev.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b < 90.0 and b > moderate_prev:
            moderate_prev = b

    critical = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if need_units >= 2:
        if critical:
            bid = max(58.0, moderate_prev + 2.0 if moderate_prev > 0 else 58.0)
        elif pressured:
            bid = max(42.0, moderate_prev + 1.5 if moderate_prev > 0 and moderate_prev < 75.0 else 42.0)
        else:
            if moderate_prev > 0:
                bid = max(24.0, min(48.0, moderate_prev - 6.0))
            else:
                bid = 26.0
    else:
        if critical:
            bid = max(88.0, highest_prev + 2.0 if highest_prev > 0 else 88.0)
        elif pressured:
            if highest_prev >= 100.0:
                bid = 72.0
            else:
                bid = max(60.0, highest_prev + 1.5 if highest_prev > 0 else 60.0)
        else:
            if highest_prev >= 100.0:
                bid = 34.0
            elif highest_prev >= 70.0:
                bid = 46.0
            else:
                bid = max(36.0, highest_prev + 1.0 if highest_prev > 0 else 36.0)

    if len(dangerous_prev) >= 2 and not critical:
        bid = min(bid, 38.0 if need_units >= 2 else 30.0)

    reserve_target = 0.0
    if day_context['day'] <= 3:
        reserve_target = 220.0
    elif day_context['day'] <= 6:
        reserve_target = 140.0
    else:
        reserve_target = 70.0

    max_affordable = budget
    if budget > reserve_target:
        max_affordable = budget - reserve_target + min(25.0, DAILY_SALARY * 0.35)

    if critical:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # If we are already in danger, prioritize survival with a high bid.
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        # No competition: bid low to conserve budget.
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Read yesterday's bid pressure from alive opponents only.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate number of water units available; use int() to avoid float index issues.
    # (We don't index arrays, but keep consistent with rule.)
    supply_units = int(supply / WATER_REQ) if WATER_REQ > 0 else 0
    # If supply is low, competition is tighter; increase bid.
    supply_tightness = 0.0
    if supply_units <= 1:
        supply_tightness = 1.0
    elif supply_units == 2:
        supply_tightness = 0.6
    else:
        supply_tightness = 0.3

    # Base willingness to bid.
    # Players like Alex/Cindy previously bid around/above ~100 and survived; emulate when safe.
    # Use highest_prev_bid to decide whether to match pressure.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure: either match with enough to beat them, or go defensive if low HP.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            # Try to slightly undercut/beat the top bidder depending on our HP.
            target = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.65)
    else:
        # Moderate pressure: bid enough to compete but conserve.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.75
        else:
            # Scale with tightness and yesterday's second-highest bid.
            target = max(second_prev_bid + 1.5, DAILY_SALARY * (0.45 + 0.25 * supply_tightness))

    # Convert target into final bid bounded by budget.
    # Also cap to avoid overspending when budget is low.
    # If budget is insufficient, spend what we can.
    bid = min(float(budget), float(target))

    # If our HP is very low, ensure we spend close to budget to avoid elimination.
    if hp <= 1:
        bid = min(float(budget), max(bid, DAILY_SALARY * 0.9))

    # Never negative.
    if bid < 0:
        bid = 0.0

    return bid

